vec2 screen2uv(vec2 glCoord, vec2 glRes)
{
    return 2.0 * (glCoord.xy - 0.5 * glRes.xy) / glRes.y; 
}


void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uvFrag = screen2uv(fragCoord.xy, iResolution.xy);
    vec2 uvMouse = screen2uv(iMouse.xy, iResolution.xy);
    vec2 uvBounds = screen2uv(iResolution.xy, iResolution.xy);


    vec2 densSin = sin(uvFrag * iTime);
    vec2 densCos = cos(uvFrag * iTime);

    vec3 color = vec3(0.34, 0.17, 0.78) * (densSin.y + densSin.x);


    // Output to screen
    fragColor = vec4(color, 1.0);
}
